class Solution {
public:
    int longestValidParentheses(string s) {
        int n=s.size();
        if (n<2) return 0;
        stack<int> st;
        vector<int> dp(n, 0);

        int ans=0;
        for(int i=0; i<n; i++){
            if (s[i]=='(') {
                st.push(i);
            }
            else{ //s[i]=')'
                if (!st.empty()){
                    int x=st.top();
                    dp[i]=i-x+1;//substring s[x:i+1] is valid
                    if (x>=1) dp[i]+=dp[x-1];//concatenate with substring
                //    cout<<i<<"->"<<x<<":"<<dp[i]<<endl;
                    st.pop();
                }
            }
            ans=max(ans, dp[i]);
        }
        return ans;
    }
};,49,https://leetcode.com/problems/longest-valid-parentheses,https://leetcode.com/problems/longest-valid-parentheses/solutions/3761737/unique-sol-c-uses-stack-dp-w-8-test-cases/

class Solution {
public:
    bool isSafe(vector<vector<char>>& board, int cur_row, int cur_col, char value){
        //row check
        for(int i=0; i<9; i++){
            if(board[i][cur_col] == value && i != cur_row){
                return false;
            }
        }

        //column check
        for(int i=0; i<9; i++){
            if(board[cur_row][i] == value && i != cur_col){
                return false;
            }
        }

        //3x3 matrix check
        for(int i=0; i<9; i++){
            int x = 3*(cur_row/3)+(i/3);
            int y = 3*(cur_col/3)+(i%3);
            if(board[x][y] == value && x != cur_row && y != cur_col){
                return false;
            }
        }

        return true;
    }


    bool isValidSudoku(vector<vector<char>>& board) {
        for(int i=0; i<9; i++){
            for(int j=0; j<9; j++){
                if(board[i][j] != '.'){
                    if(isSafe(board, i, j, board[i][j]) == false){
                        return false;
                    }
                }
            }
        }
        return true;
    }
};,37,https://leetcode.com/problems/valid-sudoku,https://leetcode.com/problems/valid-sudoku/solutions/4392173/easy-c-solution-beats-100/

class Solution {
public:
    vector<vector<int>> ans; // 2 D vector to store our answer
    void solve(int i, vector<int>& arr, vector<int>& temp, int target)
    {
        // if our target becomes zero at any point, then yess!! we wil find a possible combination
        if(target == 0) 
        {
            ans.push_back(temp); // include that combination in our answer
            return; // and then return, we are now not gonna explore more possiblity
        }

        // if at any point target becomes less than zero, then simply return, saying that no it is notpossible to our target combination sum
        if(target < 0)
            return;

        // if index crosses the last index, we will return saying that no more element is left to choosee
        if(i == arr.size())
            return;

        // As we dicussed for every element we have two choices whether to include in our answer or not include in our answer. 
		//so now, we are doing that

        // we are not taking the ith element,
        // so without decreasing sum we will move to next index because it will not contribute in making our sum
        solve(i + 1, arr, temp, target);

        // we are taking the ith element and not moving onto the next element because it may be possible that this element again contribute in making our sum.
        // but we decrease our target sum as we are consediring that this will help us in making our target sum

        temp.push_back(arr[i]); // including ith element
        solve(i, arr, temp, target - arr[i]); // decreasing sum,and call again function
        temp.pop_back(); // backtrack

    }
    vector<vector<int>> combinationSum(vector<int>& arr, int target) {
        ans.clear(); // clear global array, make to sure that no garbage value is present in it

        vector<int> temp; // temporary vector that tries all possible combination

        solve(0, arr, temp, target); // calling function, and see we start from index zero

        return ans; // finally return the answer array
    }
};,40,https://leetcode.com/problems/combination-sum,https://leetcode.com/problems/combination-sum/solutions/1777334/c-detailed-explanation-w-tree-diagram-recursion-backtracking-each-step-explained/

/**
 * @param {number[]} candidates
 * @param {number} target
 * @return {number[][]}
 */
var combinationSum2 = function(candidates, target) {
    candidates = candidates.sort((a, b) => a - b)
    const result = []

    const backtracking = (curr, remaining, target) => {
        if (target < remaining[0] || !remaining.length) return

        for (let i = 0; i < remaining.length; i++) {
            if (i > 0 && remaining[i-1] === remaining[i]) {
                continue
            }
            const number = remaining[i]
            if (number > target) return

            const newCurr = [...curr]
            newCurr.push(number)

            if (target - number === 0) {
                return result.push(newCurr)
            }

            backtracking(newCurr, remaining.slice(i+1), target - number)
        }
    }

    backtracking([], candidates, target)

    return result
