class Solution {
public:

    int cal(int n, int r)
    {
        long long p=1, k=1;
        if (n-r<r)
            r=n-r;
        if(r!=0) {
            while(r) {
                p*=n;
                k*=r;
                long long m=__gcd(p,k);
                p/=m;
                k/=m;
                n--;
                r--;
            }
        }
        else
            p=1;
        return p;
    }
    int uniquePaths(int m, int n) {
        return cal(m+n-2,n-1);
    }
};,71,https://leetcode.com/problems/unique-paths,https://leetcode.com/problems/unique-paths/solutions/3996091/unique-paths/

