class Solution {
public:

    string addBinary(string a, string b) {


        if(b.size() > a.size()) swap(a,b);


        while(b.size() < a.size()) b = "0" + b;

        int carry = 0;

        string res = "";

        for(int i = b.size()-1; i >= 0 ; --i)
        {

             if(b[i] == '1' && a[i]=='1')
             {

                if(carry == 0) res = "0" + res;

                else res = "1" + res;

                carry = 1;
             }

             else if(b[i] =='0' && a[i] =='0')
             {

                if(carry == 0) res = "0" + res;

                else
                {
                    res = "1" + res;
                    carry = 0;
                }
             }

             else if((b[i]=='0' && a[i]=='1') || (b[i]=='1' && a[i] == '0'))
             {

                if(carry == 0) res = "1" + res;

                else res = "0" + res;

             }

        }

        if(carry == 1) res = "1" + res;

        return res;
