class Solution {

    /*
        Time Complexity : O(N)
        Space Complexity : O(N)
    */

private:
    int n;

    void getNextSmallerIdx(vector<int>& res, vector<int>& heights){
        stack<int> s1;
        s1.push(-1);

        for(int i=n-1; i>=0; i--){
            int curr = heights[i];
            while(s1.top() != -1 and heights[s1.top()] >= curr){
                s1.pop();
            }

            res[i] = s1.top();
            s1.push(i);
        }
    }

    void getPrevSmallerIdx(vector<int>& res, vector<int>& heights){
        stack<int> s1;
        s1.push(-1);

        for(int i=0; i<n; i++){
            int curr = heights[i];
            while(s1.top() != -1 and heights[s1.top()] >= curr){
                s1.pop();
            }

            res[i] = s1.top();
            s1.push(i);
        }
    }

public:
    int largestRectangleArea(vector<int>& heights) {
        n = heights.size();
        int res = 0;
        vector<int> nextSmaller(n), prevSmaller(n);

        getNextSmallerIdx(nextSmaller, heights);
        getPrevSmallerIdx(prevSmaller, heights);

        for(int i=0; i<n; i++){
            int currL = heights[i];
            if(nextSmaller[i] == -1) nextSmaller[i] = n;

            int currB = nextSmaller[i] - prevSmaller[i] - 1;
            int area = currL * currB;
            res = max(area, res);
        }

        return res;
    }
};,68,https://leetcode.com/problems/largest-rectangle-in-histogram,https://leetcode.com/problems/largest-rectangle-in-histogram/solutions/3692231/c-using-stack-brute-and-optimised-both-t-c-o-n-s-c-o-n/

function maximalRectangle(aa) {
    let m = aa.length,
        n = aa[0].length;

    let heights = new Array(n + 1).fill(0), // this row heights, last col is 0
        maxArea = 0;

    for (let r = 0; r < m; r++) {
        let cols = []; // prev increasing columns - stack
        cols.top = () => cols[cols.length - 1]; // get column left on top of stack

        for (let c = 0; c <= n; c++) {
            if (c < n) {
                if (aa[r][c] === "1") heights[c]++;
                else heights[c] = 0;
            }

            while (cols.length && heights[cols.top()] > heights[c]) {
                let height = heights[cols.pop()]; // prev column height
                let width = cols.length ? c - cols.top() - 1 : c; // prev prev column to cur column width
                maxArea = Math.max(maxArea, width * height);
            }
            cols.push(c);
        }
    }
    return maxArea;
