/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseBetween(ListNode* head, int left, int right) {
        ListNode *dummy = new ListNode();
        dummy -> next = head;
        ListNode *curr = NULL, *prev = NULL, *tmp = head, *tmp1 = dummy;
        int count = 1;
        while(tmp != NULL){
            if(count == left - 1)
                tmp1 = tmp;
            else if(count == left){
                curr = tmp;
                auto x = tmp;
                while(count != right + 1){
                    auto after = curr -> next;
                    curr -> next = prev;
                    prev = curr;
                    curr = after;
                    count++;
                }
                tmp1 -> next = prev;
                x -> next = curr;
                return dummy -> next;
            }
            count++;
            tmp = tmp -> next;
        }
        return head;   
    }
};,108,https://leetcode.com/problems/reverse-linked-list-ii,https://leetcode.com/problems/reverse-linked-list-ii/solutions/4015221/clean-best-c-code/

