                    TreeNode* target = clone(oldroot);
                    root->left = target;
                    tmp.push_back(root);

                    if(oldroot!=nullptr){
                        TreeNode* tmpold = oldroot;
                        while(tmpold->right!=nullptr){
                            TreeNode* nonroot = new TreeNode(i);
                            TreeNode *tright = tmpold->right;
