class Solution {
public:

    pair<int,bool> helper(TreeNode* root){
        if(root==NULL){
            return {0,true};
        }

        auto leftans=helper(root->left);
        if(!leftans.second){
            return {0,false};
        }

        auto rightans=helper(root->right);
        if(!rightans.second){
            return {0,false};
        }

        int lh=leftans.first,rh=rightans.first;
        pair<int,bool> p;
        p.first=1+max(lh,rh);
        p.second=abs(lh - rh) <= 1;
        return p;
    }

    bool isBalanced(TreeNode* root) {
        return helper(root).second;
    }
