class Solution {
public:
    ListNode* sortList(ListNode* head) {
        //If List Contain a Single or 0 Node
        if(head == NULL || head ->next == NULL)
            return head;


        ListNode *temp = NULL;
        ListNode *slow = head;
        ListNode *fast = head;

        // 2 pointer appraoach / turtle-hare Algorithm (Finding the middle element)
        while(fast !=  NULL && fast -> next != NULL)
        {
            temp = slow;
            slow = slow->next;          //slow increment by 1
            fast = fast ->next ->next;  //fast incremented by 2

        }   
        temp -> next = NULL;            //end of first left half

        ListNode* l1 = sortList(head);    //left half recursive call
        ListNode* l2 = sortList(slow);    //right half recursive call

        return mergelist(l1, l2);         //mergelist Function call

    }

    //MergeSort Function O(n*logn)
    ListNode* mergelist(ListNode *l1, ListNode *l2)
    {
        ListNode *ptr = new ListNode(0);
        ListNode *curr = ptr;

        while(l1 != NULL && l2 != NULL)
        {
            if(l1->val <= l2->val)
            {
                curr -> next = l1;
                l1 = l1 -> next;
            }
            else
            {
                curr -> next = l2;
                l2 = l2 -> next;
            }

        curr = curr ->next;

        }

        //for unqual length linked list

        if(l1 != NULL)
        {
            curr -> next = l1;
            l1 = l1->next;
        }

        if(l2 != NULL)
        {
            curr -> next = l2;
            l2 = l2 ->next;
        }

        return ptr->next;
    }
};,36,https://leetcode.com/problems/sort-list,https://leetcode.com/problems/sort-list/solutions/1795126/c-merge-sort-2-pointer-easy-to-understand/

var maxPoints = function (ps) {
    function areSameLine([x1, y1], [x2, y2], [x3, y3]) {
        if (
            (x1 == x2 && x2 == x3) || //
            (y1 == y2 && y2 == y3)
        )
            return true;

        if (
            x1 == x2 || //
            x2 == x3 ||
            y1 == y2 ||
            y2 == y3
        )
            return false;

        const s1 = (y1 - y2) / (x1 - x2);
        const s2 = (y2 - y3) / (x2 - x3);
        return s1 === s2;
    }

    let max = 1;
    for (let i = 0; i < ps.length; i++)
        for (let j = i + 1; j < ps.length; j++) {
            let count = 2;
            for (let k = j + 1; k < ps.length; k++)
                if (areSameLine(ps[i], ps[j], ps[k])) {
                    count++;
                }
            max = Math.max(max, count);
        }
    return max;
};,100,https://leetcode.com/problems/max-points-on-a-line,https://leetcode.com/problems/max-points-on-a-line/solutions/3337644/javascript-149-max-points-on-a-line/

class Solution {
    public int findMin(int[] nums) {
        return findMin(nums, 0, nums.length-1);
    }
    public int findMin(int[] nums, int left, int right)
    {
        if(right==left)
        {
            return nums[left];
        }
        if(right == left +1)
        {
            return Math.min(nums[left], nums[right]);
        }
        // 3 3 1 3 3 3
        int middle = (right-left)/2 + left;
        // already sorted
        if(nums[right] > nums[left])
        {
            return nums[left];
            //right shift one
        }
        else if(nums[right] == nums[left])
        {
            return findMin(nums, left+1, right);
            //go right
        }
        else if(nums[middle] >= nums[left])
        {
            return findMin(nums, middle, right);
        }
        else
        {
            return findMin(nums, left, middle);
        }
    }
},9,https://leetcode.com/problems/find-minimum-in-rotated-sorted-array-ii,https://leetcode.com/problems/find-minimum-in-rotated-sorted-array-ii/solutions/3506964/java-solution-for-find-minimum-in-rotated-sorted-array-ii-problem/

