class Trie {
public:
    Node* root;
    Trie() {
        root=new Node();
    }

    void insert(string word) {
        Node* node=root;
        for(int i=0;i<word.size();i++)
        {
            if(!node->containsKey(word[i]))
            {
                node->put(word[i],new Node());
            }
            node=node->links[word[i]-'a'];
        }
        node->setEnd();
    }

    bool search(string word) {
        Node* node=root;
        for(int i=0;i<word.size();i++)
        {
            if(!node->containsKey(word[i]))
            {
                return false;
            }
            node=node->get(word[i]);
        }
        return node->isEnd();
    }

    bool startsWith(string prefix) {
        Node* node=root;
        for(int i=0;i<prefix.size();i++)
        {
            if(!node->containsKey(prefix[i]))
            {
                return false;
            }
            node=node->get(prefix[i]);
        }
        return true;
    }
};,109,https://leetcode.com/problems/implement-trie-prefix-tree,https://leetcode.com/problems/implement-trie-prefix-tree/solutions/3305906/daily-leetcode-solution-easy-c-solution/

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size();
        int len = INT_MAX;
        long long sum = 0;
        int j = 0;
        for(int i=0;i<n;i++){
            sum += nums[i];
            while(sum-nums[j] >= target){ // Not making the window size lesser than target
                sum -= nums[j];
                j++;
            }
             if(sum >= target){ // Necessary Conditions
                len = min(len,i-j+1); // Storing the minimum’s of sliding window
            }
        }
        return len == INT_MAX ? 0 : len; 
    }
};,6,https://leetcode.com/problems/minimum-size-subarray-sum,https://leetcode.com/problems/minimum-size-subarray-sum/solutions/3725517/q209-accepted-c-two-pointer-sliding-win-easiest/

class Solution {
public:
    vector<int> findOrder(int numCourses, vector<vector<int>> &prerequisites){
        vector<int> adj[numCourses];

        // Creating Adjacency List
        for (auto it : prerequisites){
            adj[it[1]].push_back(it[0]);
        }

        return using_kahnAlgo(numCourses, adj);
    }

    vector<int> using_kahnAlgo(int V, vector<int> adj[]){

        vector<int> indegree(V, 0);

        for (int i = 0; i < V; i++){
            for (int adjNode : adj[i]){
                indegree[adjNode]++; // calculating indegree of every node
            }
        }

        queue<int> q;
        for (int i = 0; i < V; i++){
            if (indegree[i] == 0){
                q.push(i); // pushing starting sources
            }
        }

        vector<int> topo;
        while (!q.empty()){
            int node = q.front();
            q.pop();

            topo.push_back(node);

            for (int adjNode : adj[node]){
                indegree[adjNode]--;

                // new start points
                if (indegree[adjNode] == 0){
                    q.push(adjNode);
                }
            }
        }

        if (topo.size() == V){
            return topo;
        }

        return {};
    }
};
