class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        unordered_map<int,int> mp;
        priority_queue<int> pq;
        vector<int> res;
        int i=0,j=0;
        while(j<nums.size()){
            mp[nums[j]]++;
            pq.push(nums[j]);
            if(j-i+1<k){
                j++;
            }
            else if(j-i+1==k){
                res.push_back(pq.top());
                mp[nums[i]]--;
                while(!pq.empty() && mp[pq.top()]==0){
                    pq.pop();
                }
                i++;
                j++;
            }
        }
        return res;
    }
