/**
 * Using a prefix sum array
 *
 * <pre>
 * prefixSum(ABCD) = prefixSum(OD) − prefixSum(OB) − prefixSum(OC) + prefixSum(OA)
 * </pre>
 *
 * Time Complexity: NumArray() -> O(R*C). sumRange() -> O(1)
 *
 * Space Complexity: O(R*C)
 *
 * R = Number of rows. C = Number of columns.
 */
class NumMatrix {

    int[][] prefixSum;

    public NumMatrix(int[][] matrix) {
        if (matrix == null) {
            throw new IllegalArgumentException("Input matrix is null");
        }

        int m = matrix.length;
        int n = matrix[0].length;
        prefixSum = new int[m + 1][n + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                prefixSum[i][j] = prefixSum[i - 1][j] + prefixSum[i][j - 1] - prefixSum[i - 1][j - 1]
                        + matrix[i - 1][j - 1];
            }
        }
    }

    public int sumRegion(int row1, int col1, int row2, int col2) {
        return prefixSum[row2 + 1][col2 + 1] - prefixSum[row2 + 1][col1] - prefixSum[row1][col2 + 1]
                + prefixSum[row1][col1];
    }
},64,https://leetcode.com/problems/range-sum-query-2d-immutable,https://leetcode.com/problems/range-sum-query-2d-immutable/solutions/1495052/java-tc-init-o-r-c-sumrange-o-1-using-prefix-sum/

class NumArray {
public:
    vector<int> st;
    vector<int> vals;
    int n;
    NumArray(vector<int>& nums): n(nums.size()), st(4*nums.size(),0) {
        vals = nums;
        build(0, 0, n-1);
    }

    void build(int node, int start, int end) {
        if (start == end) {
            st[node] = vals[start];
            return;
        }
        int mid = (start+end)/2;
        build(2*node+1, start, mid);
        build(2*node+2, mid+1, end);
        st[node] = st[2*node+1]+st[2*node+2];
    }

    void updateST(int node, int start, int end, int index, int val) {
        if (start == end) {
            st[node] = val;
            return;
        }
        int mid = (start+end)/2;
        if (index<=mid) updateST(2*node+1, start, mid, index, val);
        else updateST(2*node+2, mid+1, end, index, val);
        st[node] = st[2*node+1]+st[2*node+2];
    }

    void update(int index, int val) {
        updateST(0, 0, n-1, index, val);
        vals[index] = val;
    }

    int sumRangeHelper(int node, int start, int end, int left, int right) {
        if (start>right || end<left) return 0;
        if (start>=left && end<=right) return st[node];
        int mid = (start+end)/2;
        int leftSum = sumRangeHelper(2*node+1, start, mid, left, right);
        int rightSum = sumRangeHelper(2*node+2, mid+1, end, left, right);
        return leftSum+rightSum;
    }

    int sumRange(int left, int right) {
        return sumRangeHelper(0, 0, n-1, left, right);
    }
};
