class Solution {
public:
    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {
        vector<vector<int>> graph(n);
        vector<int> indegree(n, 0), ans; //vector<int> indegree keeps count of the number of nodes approaching a node

        for(auto &e : edges){   //Creating an adjacency matrix for the given graph
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
            indegree[e[0]]++;
            indegree[e[1]]++;
        }

        queue<int> q;
        for(int i=0; i<n;i++){
            if(indegree[i]==1) q.push(i), indegree[i]--; //add all the leaf nodes to the queue
        } 

        while(!q.empty()){
            int s = q.size();
            ans.clear();
            for(int i=0; i<s;i++){
                int curr = q.front(); q.pop();
                ans.push_back(curr);
                for(auto child : graph[curr]){ //For each node, attached to the leaf niodes, we decrement the indegree i.e remove the leaf nodes connected to them. We keep on doing this until we reach the middle nodes.
                    indegree[child]--;
                    if(indegree[child]==1) q.push(child);   
                }
            }
        }
        if(n==1) ans.push_back(0); //If there is only 1 node in the graph, the min height is 0, with root being '0'
        return ans;

    }
};,146,https://leetcode.com/problems/minimum-height-trees,https://leetcode.com/problems/minimum-height-trees/solutions/1630778/c-simple-solution-topological-sort-w-explanation/

class Solution {
    public int maxCoins(int[] nums) {
        int[] dummy_num = new int[nums.length + 2];
        dummy_num[0] = dummy_num[dummy_num.length - 1] = 1;
        for(int i = 1;i <= nums.length;i ++)
            dummy_num[i] = nums[i - 1];
        int[][] dp = new int[dummy_num.length][dummy_num.length];
        for (int i = dummy_num.length - 3; i >= 0; i --) {
            for (int j = i + 2; j < dummy_num.length;j ++) {
                for (int k = i + 1; k < j; k ++)
                    dp[i][j] = Math.max(dp[i][j], dp[i][k] + dp[k][j] + dummy_num[i] * dummy_num[k] * dummy_num[j]);
            }
        }
        return dp[0][dummy_num.length - 1];
    }
