class Solution {
public:
    int longestIncreasingPath(vector<vector<int>>& matrix, int res = 0) {
        vector<pair<int, int>> dirs = {{0, 1}, {0,-1}, {1, 0}, {-1, 0}};
        auto is_valid  = [&](int i, int j) {
            if (i < 0 || i == matrix.size()) return false;
            if (j < 0 || j == matrix[0].size()) return false;
            return true;
        };

        unordered_map<string, int> cache;
        auto gen_key = [](int i, int j) { return to_string(i) + "-" + to_string(j); };

        function<int(int, int)> go = [&](auto i, auto j) {
            auto key = gen_key(i, j);
            if (cache.count(key)) return cache[key];

            int local = 1;
            for (auto dir: dirs) {
                vector<int> to = {i + dir.first, j + dir.second};
                if (is_valid(to[0], to[1]))
                    if (matrix[i][j] < matrix[to[0]][to[1]])
                        local = max(local, 1 + go(to[0], to[1]));
            }
            return cache[key] = local;
        };

        for (int i = 0; i < matrix.size(); i++)
            for (int j = 0; j < matrix[i].size(); j++) 
                res = max(res, go(i, j));
        return res;
    }
};,128,https://leetcode.com/problems/longest-increasing-path-in-a-matrix,https://leetcode.com/problems/longest-increasing-path-in-a-matrix/solutions/3320921/c-structured-clean-code-dp-dfs/

class Solution {
public:
    int dp[200][200]={};
    int m,n,ans=1;

    int solve(vector<vector<int>>& matrix,int i,int j, int prev){
        if(i<0 || i>=m || j<0 || j>=n || matrix[i][j]<=prev)return 0;
        if(dp[i][j])return dp[i][j];
        return dp[i][j]=1+max({
            solve(matrix,i+1,j,matrix[i][j]),
            solve(matrix,i,j+1,matrix[i][j]),
            solve(matrix,i-1,j,matrix[i][j]),
            solve(matrix,i,j-1,matrix[i][j])
        });
    }

    int longestIncreasingPath(vector<vector<int>>& matrix) {
        m=matrix.size(),n=matrix[0].size();
        for(int i=0;i<m;i++){
            for(int j=0;j<n;j++){
                ans=max(ans,solve(matrix,i,j,-1));
            }
        }
        return ans;
    }
