class Solution {
public:
    int kthSmallest(vector<vector<int>>& matrix, int k) {
        //M3: BS
        //find smallest right margin that countlessorEqual(right) is larger or equal to k
        m = matrix.size(), n = matrix[0].size();
        int left = matrix[0][0], right = matrix[m - 1][n - 1];
        //int ans = INT_MIN;

        while(left < right) {
            int mid = (left + right) >> 1;
            if (countLessorEqual(matrix, mid) >= k) {
                //ans = mid;
                right = mid;
            }else {
                left = mid + 1;
            }
        }
        return left; 
        //return ans;
    }

private:
    int m, n;
    int countLessorEqual(vector<vector<int>>& matrix, int mid) {
        int cnt = 0;
        for (int i = 0; i < m; ++i) {
            int coln = n - 1;
            while(coln >= 0 && matrix[i][coln] > mid) --coln;
            cnt += coln + 1;
        }
        return cnt;
    }
};,33,https://leetcode.com/problems/kth-smallest-element-in-a-sorted-matrix,https://leetcode.com/problems/kth-smallest-element-in-a-sorted-matrix/solutions/1322101/c-java-python-maxheap-minheap-binary-search-picture-explain-clean-concise/

