        int s=0;
        for (int i=0;i<n;i++)
        {
            sum+=nums[i];
            s+=nums[i]*i;
        }
        for (int i=n-1;i>=0;i--)
        {
           s=s-(nums[i]*(n-1))+(sum-nums[i]);
