class Solution {
public:
    int numberOfArithmeticSlices(vector<int>& nums) {
        int n = nums.size(), res = 0;
        if(n < 3) return 0;
        vector<int> dp(n+1, 0);
        for(int i = 3; i <= n; i++) {
            dp[i] += dp[i-1] + i-2;
        }

        int i = 0, j;
        while(i < n) {
            if(i == n-1 || i == n-2) break;
            int temp = nums[i+1] - nums[i];
            for(j = i+2; j < n; j++) {
                int diff = nums[j] - nums[j-1];
                if(diff != temp) break;
            }
            int length = j-i;
            res += dp[length];
            i = j-1;
        }
        return res;
    }
};,59,https://leetcode.com/problems/arithmetic-slices,https://leetcode.com/problems/arithmetic-slices/solutions/3726825/c-o-n-beats-100/

class Solution {
public:
    int thirdMax(vector<int>& nums) {
        long long first = LLONG_MIN;
        long long second = LLONG_MIN;
        long long third = LLONG_MIN;

        for (int num : nums) {
            if (num == first || num == second || num == third) {
                continue; // Skip duplicates
            }
            if (num > first) {
                third = second;
                second = first;
                first = num;
            } else if (num > second) {
                third = second;
                second = num;
            } else if (num > third) {
                third = num;
            }
        }

        return (third != LLONG_MIN) ? third : first;
    }
};


