class Solution {
public:
    vector<int> findDiagonalOrder(vector<vector<int>>& mat) {
        // Intution
        // The idea in here is really very simple. We know that by maintains two straps details i.e., First row + Last column and First column + Last row we can get the required elements but only the starting location changes in both the cases.
        vector<int> answer;

        vector<pair<int, int>> strap1;
        vector<pair<int, int>> strap2;

        int m = mat.size();
        int n = mat[0].size();

        for(int i = 0 ; i < n ; i++) strap1.push_back({0, i});
        for(int i = 1 ; i < m ; i++) strap1.push_back({i, n - 1});

        for(int i = 0 ; i < m ; i++) strap2.push_back({i, 0});
        for(int i = 1 ; i < n ; i++) strap2.push_back({m - 1, i});

        bool toggler = false;

        int total = strap1.size();

        int ind = 0;

        while(total --> 0){
            if(!toggler){
                int r = strap2[ind].first;
                int c = strap2[ind].second;
                while(r >= 0 and c < n){
                    answer.push_back(mat[r][c]);
                    r -= 1;
                    c += 1;
                }
            }
            else{
                int r = strap1[ind].first;
                int c = strap1[ind].second;
                while(c >= 0 and r < m){
                    answer.push_back(mat[r][c]);
                    c -= 1;
                    r += 1;
                }
            }
            if(toggler) toggler = false;
            else toggler = true;
            ind += 1;
        }

        return answer;

    }
};,89,https://leetcode.com/problems/diagonal-traverse,https://leetcode.com/problems/diagonal-traverse/solutions/3952395/c-dividing-into-two-straps-easy-solution-faster-than-100/

/**
 * Simulate Diagonal Order Traversal
 *
 * r+c determines which diagonal you are on. For ex: [2,0],[1,1],[0,2] are all
 * on same diagonal with r+c =2. If you check the directions of diagonals, first
 * diagonal is up, second diagonal is down, third one is up and so on..
 * Therefore (r+c)%2 simply determines direction. Even is UP direction. Odd is
 * DOWN direction.
 *
 * Time Complexity: O(M*N)
 *
 * Space Complexity: O(1) without considering result space.
 *
 * M = Number of rows. N = Number of columns.
 */
class Solution {
    public int[] findDiagonalOrder(int[][] matrix) {
        if (matrix == null) {
            throw new IllegalArgumentException("Input matrix is null");
        }
        if (matrix.length == 0 || matrix[0].length == 0) {
            return new int[0];
        }

        int rows = matrix.length;
        int cols = matrix[0].length;
        int[] result = new int[rows * cols];
        int r = 0;
        int c = 0;

        for (int i = 0; i < result.length; i++) {
            result[i] = matrix[r][c];
            if ((r + c) % 2 == 0) { // Move Up
                if (c == cols - 1) {
                    // Reached last column. Now move to below cell in the same column.
                    // This condition needs to be checked first due to top right corner cell.
                    r++;
                } else if (r == 0) {
                    // Reached first row. Now move to next cell in the same row.
                    c++;
                } else {
                    // Somewhere in middle. Keep going up diagonally.
                    r--;
                    c++;
                }
            } else { // Move Down
                if (r == rows - 1) {
                    // Reached last row. Now move to next cell in same row.
                    // This condition needs to be checked first due to bottom left corner cell.
                    c++;
                } else if (c == 0) {
                    // Reached first columns. Now move to below cell in the same column.
                    r++;
                } else {
                    // Somewhere in middle. Keep going down diagonally.
                    r++;
                    c--;
                }
            }
        }

        return result;
    }
},64,https://leetcode.com/problems/diagonal-traverse,https://leetcode.com/problems/diagonal-traverse/solutions/1517538/java-tc-o-m-n-sc-o-1-concise-one-pass-solution/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    // time/space: O(n)/O(1)
    vector<int> findMode(TreeNode* root) {
        int prev_value = INT_MAX;
        int curr_freq = 0;
        int max_freq = 0;
        vector<int> modes;

        // Morris Traversal
        TreeNode* curr = root;
        while (curr != NULL) {
            if (curr->left == NULL) {
                updateModes(curr->val, prev_value, curr_freq, max_freq, modes);
                curr = curr->right;
                continue;
            }
            TreeNode* prev = curr->left;
            while ((prev->right != NULL) && (prev->right != curr)) prev = prev->right;
            if (prev->right == NULL) {
                prev->right = curr;
                curr = curr->left;
            }
            else {
                prev->right = NULL;
                updateModes(curr->val, prev_value, curr_freq, max_freq, modes);
                curr = curr->right;
            }
        }

        return modes;
    }
private:
    void updateModes(int curr_value, int& prev_value, int& curr_freq, int& max_freq, vector<int>& modes) {
        // update the current frequency
        curr_freq = (prev_value == curr_value) ? (curr_freq + 1) : 1;
        prev_value = curr_value;

        // update the maximum frequency and `modes`
        if (curr_freq > max_freq) {
            max_freq = curr_freq;
            modes = vector<int>({curr_value});
        }
        else if (curr_freq == max_freq) {
            modes.push_back(curr_value);
        }
    }
};,111,https://leetcode.com/problems/find-mode-in-binary-search-tree,https://leetcode.com/problems/find-mode-in-binary-search-tree/solutions/4233340/c-morris-traversal-without-using-any-extra-space/

