/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    map<int,int>mp;
    int findSum(TreeNode* root){
        if(!root)return 0;
        int lsum=findSum(root->left);
        int rsum=findSum(root->right);
        mp[root->val+lsum+rsum]++;
        return root->val+lsum+rsum;
    }


    vector<int> findFrequentTreeSum(TreeNode* root) {
        vector<int>ans;
        findSum(root);
        priority_queue<pair<int,int>>q;
        for(auto it=mp.begin();it!=mp.end();it++){
            q.push({it->second,it->first});
        }
        int max_freq=q.top().first;
        while(!q.empty() && q.top().first==max_freq){
            ans.push_back(q.top().second);
            q.pop();
        }
        return ans;
    }
};,167,https://leetcode.com/problems/most-frequent-subtree-sum,https://leetcode.com/problems/most-frequent-subtree-sum/solutions/3101974/simple-solution-maps-max-heap-o-n-solution/

class Solution {
public:
    using VI = vector<int>;
    using VVI = vector<VI>;
    int findRotateSteps(string ring, string key, int INF = 1e9 + 7) {
        int M = ring.size(),
            N = key.size();
        auto steps = [=](auto i, auto k) {
            return min(abs(i - k), M - abs(i - k)); // ⭐️ minimum x steps to rotate the ring from i..k (🚫 without wrap-around, ✅ with wrap-around)
        };
        VVI dp(M, VI(N + 1, INF));            // 🤔 memo
        for (auto i{ 0 }; i < M; ++i)
            for (auto k{ 0 }; k < M; ++k)
                dp[i][N] = 0;                 // 🛑 base case
        for (auto j{ N - 1 }; 0 <= j; --j)    // key j
            for (auto i{ 0 }; i < M; ++i)     // cur i
                for (auto k{ 0 }; k < M; ++k) // pre i (optimal k-th value is found as the recursive stack unwinds)
                    if (ring[k] == key[j])
                        dp[i][j] = min(dp[i][j], 1 + steps(i, k) + dp[k][j + 1]); // 🎯 min steps to reach key[j] from each ring[i] is the min steps to reach key[j + 1] from ring[k], 🔍 find optimal k via exhaustive search
        return dp[0][0]; // 🚀 when the ring starts at i = 0 (ie. index 0 is aligned with the 12:00 direction of the ring) return the min steps to construct key[j = 0..N - 1]
    }
};,177,https://leetcode.com/problems/freedom-trail,https://leetcode.com/problems/freedom-trail/solutions/1147789/the-art-of-dynamic-programming/

class Solution {
    public int longestPalindromeSubseq(String s) {
        if(s.length()<=1){
            return 1;
        }
        String rev="";
        for(int i=0; i<s.length() ; i++){
            rev=s.charAt(i)+rev+"";
        }
        return lcs(s,rev);
    }
    public int lcs(String s, String t){
        int dp[][]=new int[s.length()+1][t.length()+1];
        for(int i=1; i<dp.length ; i++){
            for(int j=1; j<dp[0].length ; j++){
                if(s.charAt(i-1)==t.charAt(j-1)){
                    dp[i][j]=1+dp[i-1][j-1];
                }else{
                    int a=dp[i][j-1];
                    int b=dp[i-1][j];
                    dp[i][j]=Math.max(a,b);
                }
            }
        }
        return dp[dp.length-1][dp[0].length-1];
    }
