class Solution {
public:
    int helper(int ind, int mask, int n){
        if(ind > n)
            return 1;
        int cnt = 0;
        for(int i = 1 ; i <= n ; i++){
            if(!(mask & (1 << i))){
                if((i % ind == 0) || (ind % i == 0))
                    cnt += helper(ind + 1, mask | (1 << i), n);
            }
        }
        return cnt;
    }
    int countArrangement(int n) {
        return helper(1, 0, n);
    }
