        if(!root)
        return;
        if(!root->left and !root->right){
            s+=root->val;
            root->val=s;
            return;

        }
        solve(root->right);
        s+=root->val;
        root->val=s;

        solve(root->left);


    }

    TreeNode* convertBST(TreeNode* root) {
        if(!root)
        return NULL;

        solve(root);
        return root;

    }
