class Solution {
public:
    vector<double> averageOfLevels(TreeNode* root) {
        vector<double>ans;
        queue<TreeNode*>q;
        q.push(root);
        while(!q.empty()){
            int size=q.size();

            double w=0;
            for(int i=0;i<size;i++){
                TreeNode* x=q.front();
                q.pop();
                if(x->left!=NULL){
                    q.push(x->left);
                }
                if(x->right!=NULL){
                    q.push(x->right);
                }
                w=w+x->val;

            }
            ans.push_back(w/size);
        }
        return ans;
