class Solution {
public:
    int findKthNumber(int m, int n, int k) {
	    auto check = [&](int mid) {
		    int cnt = 0 ;
		    for (int i = 1 ; i <= n ; i++) {
			    cnt += min(m, (mid / i));
		    }
		return cnt >= k;
	};
	int lo = 0 , hi = n * m, ans = 0  ;
	while (lo <= hi) {
		int mid = (lo + hi) / 2 ;
		if (check(mid)) {
			ans = mid ;
			hi = mid - 1 ;
		} else {
			lo = mid + 1;
		}
	}
    return ans ; 
    }
