class Solution {
public:
    int traversal(int i, int j, vector<vector<int>>& grid, vector<vector<int>>& vis) {
        int m = grid.size(), n = grid[0].size();
        int cnt = 0;
        queue <pair<int, int>> q;
        q.push({i, j});
        vis[i][j] = 1;
        int drow[] = {-1, 0, 1, 0};
        int dcol[] = {0, 1, 0, -1};
        while (!q.empty()) {
            int r = q.front().first;
            int c = q.front().second;
            q.pop();
            cnt++;
            for (int i = 0; i < 4; i++) {
                int nr = r + drow[i];
                int nc = c + dcol[i];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n
                    && grid[nr][nc] > 0 && !vis[nr][nc]) {
                       q.push({nr, nc});
                       vis[nr][nc] = 1;
                   }
            }
        }
        return cnt;
    }

    int maxAreaOfIsland(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> vis(m, vector<int>(n, 0));
        int maxArea = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0 && !vis[i][j]) {
                    int area = traversal(i, j, grid, vis);
                    maxArea = max (maxArea, area);
                }
            }
