class Solution {
    vector<vector<int>> dp;
public:
    int maxProfit(vector<int>& prices, int fee) {
        dp = vector<vector<int>> (int(prices.size())+1, vector<int>(2, -1));
        return helper(prices, fee, 0, 1);
    }

    int helper(vector<int>& prices, int & fee, int i, int buy) {
        if (i==prices.size()) return 0;
        if (dp[i][buy] != -1) return dp[i][buy];

        if (buy) {
            int x = helper(prices, fee, i+1, 0) - prices[i] - fee; // buy
            int y = helper(prices, fee, i+1, 1); // don't buy
            return dp[i][buy] = max(x, y);
        }

        int x = helper(prices, fee, i+1, 1) + prices[i]; // sell
        int y = helper(prices, fee, i+1, 0); // don't sell
        return dp[i][buy] = max(x, y);
    }
};,135,https://leetcode.com/problems/best-time-to-buy-and-sell-stock-with-transaction-fee,https://leetcode.com/problems/best-time-to-buy-and-sell-stock-with-transaction-fee/solutions/3682835/brute-force-optimal-solution/

class RangeModule {
public:
    void addRange(int left, int right) {
        auto l = invals.upper_bound(left), r = invals.upper_bound(right); 
        if (l != invals.begin()) {
            l--;
            if (l->second < left) l++;
        }
        if (l != r) {
            left = min(left, l->first);
            right = max(right, (--r)->second);
            invals.erase(l,++r);
        }
        invals[left] = right;
    }

    bool queryRange(int left, int right) {
        auto it = invals.upper_bound(left);
        if (it == invals.begin() || (--it)->second < right) return false;
        return true;
    }

    void removeRange(int left, int right) {
        auto l = invals.upper_bound(left), r = invals.upper_bound(right); 
        if (l != invals.begin()) {
            l--;
            if (l->second < left) l++;
        }
        if (l == r) return;
        int l1 = min(left, l->first), r1 = max(right, (--r)->second);
        invals.erase(l, ++r);
        if (l1 < left) invals[l1] = left;
        if (r1 > right) invals[right] = r1;
    }
private:
    map<int, int> invals;
};,179,https://leetcode.com/problems/range-module,https://leetcode.com/problems/range-module/solutions/108912/c-vector-o-n-and-map-o-logn-compare-two-solutions/

class Solution {
public:
    int LCSubStr(vector<int>& X, vector<int>& Y, int n, int m){
   int LCSuff[n + 1][m + 1];
    int result = 0; 

    /* LCSuff[m+1][n+1] in
        bottom up fashion. */
    for (int i = 0; i <= n; i++){

        for (int j = 0; j <= m; j++){
            // The first row and first column
            // entries have no logical meaning,
            if (i == 0 || j == 0)
                LCSuff[i][j] = 0;

            else if (X[i - 1] == Y[j - 1]) {
                LCSuff[i][j] = LCSuff[i - 1][j - 1] + 1;
                result = max(result, LCSuff[i][j]);
            }
            else
                LCSuff[i][j] = 0;
        }
    }
    return result;
}

