class Solution {
public:
    int rectangleArea(vector<vector<int>>& rectangles) {
        // find unique y's so the adjacent y_diff are heights
        // sweep all rectangles along x for each height
        set<int> ys;
        for (auto const & r: rectangles)
        {
            ys.insert(r[1]);
            ys.insert(r[3]);
        }
        // sort rectangle with x_start
        sort(rectangles.begin(), rectangles.end(), [](auto const & r1, auto const & r2){return r1[0] < r2[0];});

        // sweep from bottom to top
        int prev_y= *ys.begin();
        long long res = 0;
        int mod = pow(10, 9)+7;
        for (auto y: ys)
        {
            long long height = y-prev_y;
            long long x_start = rectangles.front()[0];
            long long x_end = x_start;
            for (auto const & r: rectangles)
            {
                // check if r fully occupy in between y and prev_y
                if (r[1] <= prev_y && r[3] >=y)
                {
                    if (r[0] > x_end)
                    {
                        res+= height * (x_end-x_start) % mod;
                        x_start = r[0];
                    }
                    if (r[2] > x_end)
                    {
                        x_end = r[2];
                    }
                }
            }
            res += height * (x_end-x_start) % mod;
            prev_y = y;
        }

        return res % mod;
    }
};,155,https://leetcode.com/problems/rectangle-area-ii,https://leetcode.com/problems/rectangle-area-ii/solutions/1419388/rectangle-area-ii-line-sweep-o-n-2-c-python/

class Solution {
public:
  int kSimilarity(string A, string B) {
      for (int i=0; i<A.size(); i++) {
        if (A[i]==B[i]) continue;
        vector<int> matches;
        for (int j=i+1;j<A.size();j++) { 
          if (A[j]==B[i] && A[j]!=B[j]) {
            matches.push_back(j);
            if (A[i]==B[j]) {
              swap(A[i],A[j]);
              return 1+kSimilarity(A.substr(i+1),B.substr(i+1));
            }
          }
        }
        int best=A.size()-1;
        for (int j: matches) {
            swap(A[i],A[j]);
            best = min(best, 1+kSimilarity(A.substr(i+1),B.substr(i+1)));
            swap(A[i],A[j]);
        }
        return best;
      }
      return 0;
    }
};,57,https://leetcode.com/problems/k-similar-strings,https://leetcode.com/problems/k-similar-strings/solutions/2758378/c-faster-than-all-easy/

