typedef pair<int, int> pii;
class Solution {
public:
    bool stoneGame(vector<int> &piles) {
        int n = piles.size();
        vector<vector<pii>> dp(n, vector<pii>(n));
        for (int left = n - 1; left >= 0; --left) {
            for (int right = left; right < n; ++right) {
                if (left == right) { 
                    dp[left][right] = make_pair(piles[left], 0);
                    continue;
                }
                pii pickLeft = dp[left + 1][right];
                pii pickRight = dp[left][right - 1];
                if (piles[left] + pickLeft.second > piles[right] + pickRight.second) 
                    dp[left][right] = make_pair(piles[left] + pickLeft.second, pickLeft.first);
                else
                    dp[left][right] = make_pair(piles[right] + pickRight.second, pickRight.first);
            }
        }
        auto[aliceScore, leeScore] = dp[0][n - 1];
        return aliceScore > leeScore;
    }
};,57,https://leetcode.com/problems/stone-game,https://leetcode.com/problems/stone-game/solutions/2783421/c-easy-short/

class Solution {
public:
    bool stoneGame(vector<int>& piles) {
        int n = piles.size();
        array<array<int,501>,501> dp;
        for(int i=0; i<501; ++i) for(int j=0; j<501; ++j) dp[i][j] = -1;

        auto fn = [&](auto&&fn,int i,int j) -> int {
            if(i > j) return 0;
            if(dp[i][j] != -1) return dp[i][j];
            int op1 = piles[i] + fn(fn,i+1,j);
            int op2 = piles[j] + fn(fn,i,j-1);
            return dp[i][j] = max(op1,op2);
        };
        int alice = fn(fn,0,n-1);
        int bob = reduce(begin(piles),end(piles)) - alice;
        return alice > bob;
    }
};,28,https://leetcode.com/problems/stone-game,https://leetcode.com/problems/stone-game/solutions/4270028/top-down-dp/

