class Solution {
public:
    #define mod 1000000007    //REMEMBER TO ADD THIS

    int nthMagicalNumber(int n, int a, int b) {
        //Initialize the LCM fromula  
        int lcm = (a*b)/__gcd(a,b);
        //Initializing the left and right boundary
        long long int left=min(a,b) , right=n*1LL*min(a,b);
        //our ans 
        long long int ans = 0;
        //binary search algo implementation
        while(left<=right){
            //Middle position 
            long long int mid = (left + (right-left)/2);
            //inclusion exclusion principle for position_check
            long long int position_check = mid/b + mid/a - mid/lcm ;
            //if position is low ,increment left pointer
            if(position_check < n) left = mid +1 ;
            //else our ans and decrement the right pointer
            else {
             ans=mid%mod;
             right=mid-1;
         }
        }
        return ans;
    }  
};,124,https://leetcode.com/problems/nth-magical-number,https://leetcode.com/problems/nth-magical-number/solutions/1622417/c-easy-to-solve-beginner-friendly-detailed-explanation-with-dry-run-image-based-explanation/

class Solution {
public:
    string decodeAtIndex(string s, int k) {
        long long n = 0; // Length of decoded string
        long long size = 0; // Total size of string after decoding

        // Calculate the total size and length of the decoded string
        for (char c : s) {
            if (isdigit(c)) {
                int digit = c - '0';
                size *= digit; // Update the size based on the digit
                n *= digit; // Update the length based on the digit
            } else {
                size++; // Increment size for non-digit characters
                n++; // Increment length for non-digit characters
            }
        }

        // Iterate through the string in reverse order
        for (int i = s.size() - 1; i >= 0; i--) {
            char c = s[i];
            if (isdigit(c)) {
                int digit = c - '0';
                size /= digit; // Adjust size based on the digit
                n /= digit; // Adjust length based on the digit
                k %= n; // Update k by taking modulo n
            } else {
                if (k == 0 || k == n) {
                    return string(1, c); // Return the current character if k matches length
                }
                size--; // Decrement size for non-digit characters
                n--; // Decrement length for non-digit characters
            }
        }

        return ""; // Return an empty string if k is out of bounds
    }
};,14,https://leetcode.com/problems/decoded-string-at-index,https://leetcode.com/problems/decoded-string-at-index/solutions/4095540/c-beats-100-new-approach-explained/

