class Solution {
public:
    const int mod=1e9+7;
    vector<vector<int>> dp;
    int dfs(int i, int j, int n, int goal, int k){
        if (i==0 && j==0) return dp[i][j]=1;
        if (i==0 || j==0) return dp[i][j]=0;
        if (dp[i][j]!=INT_MIN) return dp[i][j];
        long long ans=(long long)dfs(i-1, j-1, n, goal, k)*(n-j+1)%mod;//new song
        if (j>k)
            ans+=(long long)dfs(i-1, j, n, goal, k)*(j-k)%mod;//old song
        return dp[i][j]=ans%mod;
    }
    int numMusicPlaylists(int n, int goal, int k) {
        dp.assign(goal+1, vector<int>(n+1, INT_MIN));
        return dfs(goal, n, n, goal, k);
    }
};,49,https://leetcode.com/problems/number-of-music-playlists,https://leetcode.com/problems/number-of-music-playlists/solutions/3869637/simple-c-dfs-dp-iterative-dp/

class Solution {
public:
    int numMusicPlaylists(int n, int goal, int k) {
        const int mod=1e9+7;
        vector<int> dp(n+1, 0), prev(n+1, 0);
        prev[0]=1;// dp[0][0]=1
        for (int i=1; i<=goal; i++){
            for(int j=1; j<=n; j++){
                long long ans=(long long)prev[j-1]*(n-j+1)%mod;//new song
                if (j>k)
                    ans+=(long long)prev[j]*(j-k)%mod;//old song
                dp[j]=ans%mod;
            }
            prev=dp;
        }
        return dp[n];
    }
