        if (n==1) return 1;
        if (i==5) return 0;
        if (dp[i][n]!=-1) return dp[i][n];
        int ans=0;
        #pragma unroll
        for(int j: adj[i]){
            ans=(ans+f(j, n-1))%mod;
        }
        return dp[i][n]=ans;
    }
