class Solution {
public:
    vector<int> addToArrayForm(vector<int>& nums, int k) {
        vector<int>ans;
        int i = nums.size()-1; 
        int carry = 0;
        // both number and array of same size
        while(i>=0 && k>0)
        {
            int left = k%10;
            k = k/10;
            int sum = nums[i] + left + carry;
            carry = sum / 10;
            sum=sum % 10;  
            ans.push_back(sum);
            i--; 
        }
        // when array is big
        while(i>=0)
        {
            int sum = nums[i] + carry;
            carry = sum / 10;
            sum=sum % 10;  
            ans.push_back(sum);
            i--; 
        }
        // when number is big
        while(k>0)
        {
            int left = k%10;
            k = k/10;
            int sum =  left + carry;
            carry = sum / 10;
            sum=sum % 10;  
            ans.push_back(sum);
        }
        while(carry!=0)
        {
            int sum = carry;
            carry = sum / 10;
            sum=sum % 10;  
            ans.push_back(sum);
        }
        reverse(ans.begin(), ans.end());
        return ans;
    }
