class Solution {
public:
    string alphabetBoardPath(string target) 
    {
        vector<string>board =  {"abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"};
        unordered_map<char,pair<int,int>>mp;

        for(int i=0;i<board.size();i++)
        {
            string str = board[i];
            for(int j=0;j<str.length();j++)
            {
                char ch = str[j];
                mp[ch] = {i,j};
            }
        }
        int row = 0;
        int col = 0;
        int idx = 0;
        string ans="";

        while(idx < target.length())
        {
            char target_ch  = target[idx];
            int  target_row = mp[target_ch].first;
            int  target_col = mp[target_ch].second;

            if(target_ch == 'z')
            {
                //first we will be on the col 0;

                //doing the horizontal traversal
                int count = abs(col - target_col);
                while(count > 0)
                {
                    ans.push_back('L');
                    count--;
                }

                //doing the vertical traversal
                count = abs(row - target_row);
                while(count > 0)
                {
                    ans.push_back('D');
                    count--;
                }
                ans.push_back('!');
                row = target_row;
                col = target_col;
                idx++;
            }
            else
            {
                char curr_ch   = board[row][col];
                //checking the horizontal moves
                if(row < target_row)
                {
                    int count = abs(row - target_row);
                    while(count--)
                    {
                        ans.push_back('D');
                    }
                }
                else if(row > target_row)
                {
                    int count = abs(row - target_row);
                    while(count--)
                    {
                        ans.push_back('U');
                    }
                }

                //checking the horizontal moves
                if(col < target_col)
                {
                    int count = abs(col - target_col);
                    while(count--)
                    {
                        ans.push_back('R');
                    }
                }
                else if(col > target_col)
                {
                    int count = abs(col - target_col);
                    while(count--)
                    {
                        ans.push_back('L');
                    }
                }
                ans.push_back('!');
                row = target_row;
                col = target_col;
                idx++;
          }
        }
        return ans;
    }
};,145,https://leetcode.com/problems/alphabet-board-path,https://leetcode.com/problems/alphabet-board-path/solutions/3418559/runtime-0-ms-beats-100-easy-to-understand-must-see/

class Solution {
public:
    int longestCommonSubsequence(string t1, string t2) {
        int n=t1.size(),m=t2.size();
        vector<vector<int>> dp(n+1,vector<int>(m+1,0));
        for (int j=0;j<=m;j++) dp[0][j]=0;
        for (int i=0;i<=n;i++) dp[i][0]=0;

        for (int i=1;i<=n;i++){
            for(int j=1;j<=m;j++){
                if(t1[i-1]==t2[j-1]) dp[i][j]=1+dp[i-1][j-1];
                else dp[i][j]=max(dp[i][j-1],dp[i-1][j]);
            }
        }
        return dp[n][m];
    }
};,92,https://leetcode.com/problems/longest-common-subsequence,https://leetcode.com/problems/longest-common-subsequence/solutions/3685106/c-easy-tabulation-code-with-index-shifting/

class Solution {
    public int longestCommonSubsequence(String text1, String text2) {
        int[][] dp = new int[text1.length()][text2.length()];
        for(int[] arr : dp) Arrays.fill(arr, -1);
        return helper(text1, text2, text1.length() - 1, text2.length() - 1, dp);
    }

    private int helper(String str1, String str2, int ind1, int ind2, int[][] dp) {
        if(ind1 < 0 || ind2 < 0) return 0;
        if(dp[ind1][ind2] != -1) return dp[ind1][ind2];

        if(str1.charAt(ind1) == str2.charAt(ind2)) return dp[ind1][ind2] = 1 + helper(str1, str2, ind1 - 1, ind2 - 1, dp);
        return dp[ind1][ind2] = Math.max(helper(str1, str2, ind1 - 1, ind2, dp), helper(str1, str2, ind1, ind2 - 1, dp));
    }
