        int x = 0;
        vector<int> v;
        while (!q.empty())
        {
            int n1 = q.size();
            x++;
            while (n1--)
            {
                v = q.front();
                // cout << v[0] << " " << v[1] << endl;
                q.pop();
                if (v[0] - 1 >= 0 && grid[v[0] - 1][v[1]] == 0)
                {
                // cout<<v[0]-1<<" "<<v[1]<<" #"<<endl;
                    q.push({v[0] - 1, v[1]});
                    grid[v[0] - 1][v[1]] = 2;
                }
                if (v[0] + 1 < m && grid[v[0] + 1][v[1]] == 0)
                {
                // cout<<v[0]+1<<" "<<v[1]<<" #"<<endl;
                    q.push({v[0] + 1, v[1]});
                    grid[v[0] + 1][v[1]] = 2;
                }
                if (v[1] - 1 >= 0 && grid[v[0]][v[1] - 1] == 0)
                {
                // cout<<v[0]<<" "<<v[1]-1<<" #"<<endl;
                    q.push({v[0], v[1] - 1});
                    grid[v[0]][v[1] - 1] = 2;
                }
                if (v[1] + 1 < n && grid[v[0]][v[1] + 1] == 0)
                {
                // cout<<v[0]<<" "<<v[1]+1<<" #"<<endl;
                    q.push({v[0], v[1] + 1});
                    grid[v[0]][v[1] + 1] = 2;
                }
            }

            // cout << endl;
        }
        return x - 1==0?-1:x-1;
    }
