class Solution {
public:
    vector<vector<int>> groupThePeople(vector<int>& groupSizes) {
        int n=groupSizes.size();
        vector<vector<int>> mp(n+1);
        for(int i=0; i<n; i++){
            int x=groupSizes[i];
            mp[x].push_back(i);
        }
        vector<vector<int>> ans;
        for(int x=1; x<=n; x++){
            auto v=mp[x];
            int sz=v.size();
            if (sz==0) continue;
            int q=sz/x;
            for(int i=0; i<q; i++){
                vector<int> v_sz(x);
                copy(v.begin()+(i*x), v.begin()+((i+1)*x), v_sz.begin());
                ans.push_back(v_sz);
            }
        }
        return ans;
    }
