class Solution {
	public int maxSideLength(int[][] mat, int threshold) {
		int m = mat.length, n = mat[0].length;
		int[][] sum = new int[m + 1][n + 1]; // sum[i][j] is sum of all elements from rectangle (0,0,i,j) as left, top, right, bottom corresponding
		for (int r = 1; r <= m; r++) {
			for (int c = 1; c <= n; c++) {
				sum[r][c] = mat[r - 1][c - 1] + sum[r - 1][c] + sum[r][c - 1] - sum[r - 1][c - 1];
			}
		}
		int low = 1, high = Math.min(m, n);
		int ans = 0;
		while (low <= high) {
			int mid = low + (high - low) / 2;
			if (foundSquare(mat, sum, mid, threshold)) {
				ans = mid; // update the answer
				low = mid + 1; // Try to find the larger one
			} else {
				high = mid - 1;
			}
		}
		return ans;
	}

	private boolean foundSquare(int[][] mat, int[][] sum, int side, int threshold) {
		int m = mat.length, n = mat[0].length;
		for (int r = side; r <= m; r++) {
			for (int c = side; c <= n; c++) {
				if (sum[r][c] - sum[r - side][c] - sum[r][c - side] + sum[r - side][c - side] <= threshold)
					return true;
			}
		}
		return false;
	}
},33,https://leetcode.com/problems/maximum-side-length-of-a-square-with-sum-less-than-or-equal-to-threshold,https://leetcode.com/problems/maximum-side-length-of-a-square-with-sum-less-than-or-equal-to-threshold/solutions/452478/java-prefix-sum-binary-search-clean-code-o-m-n-log-min-m-n/

class Solution {
public:
    bool isPossibleDivide(vector<int>& nums, int k) {
        if (nums.size() % k != 0) {
            return false;
        }

        unordered_map<int,int> map;
        for (int num : nums) {
            map[num]++;
        }

        sort(nums.begin(), nums.end());

        for (int num : nums) {
            if (map[num] > 0) {
                for (int i = num + 1; i < num + k; i++) {
                    if (map[i] == 0) {
                        return false;
                    }
                    map[i]--;
                }
                map[num]--;
            }
        }

        return true;
    }
};
