class Solution
{

    /*
        Memoization:
        Time Complexity : O(m*n*n)
        Space Complexity : O(m*n*n)
    */

private:
    int m, n;
    int dirc[3] = {-1, 0, +1};
    int dp[71][71][71];

    int helper(int r, int c1, int c2, vector<vector<int>> &grid)
    {
        if (c1 < 0 || c1 >= n || c2 < 0 || c2 >= n)
            return -1e9;
        if (r == m)
            return 0;
        if (dp[r][c1][c2] != -1)
            return dp[r][c1][c2];

        int maxRes = 0;

        for (int k1 = 0; k1 < 3; k1++)
        {
            for (int k2 = 0; k2 < 3; k2++)
            {
                maxRes = max(maxRes, helper(r + 1, c1 - dirc[k1], c2 - dirc[k2], grid));
            }
        }

        maxRes += (c1 == c2) ? grid[r][c1] : grid[r][c1] + grid[r][c2];
        return dp[r][c1][c2] = maxRes;
    }

public:
    int cherryPickup(vector<vector<int>> &grid)
    {
        m = grid.size(), n = grid[0].size();
        memset(dp, -1, sizeof(dp));

        return helper(0, 0, n - 1, grid);
    }
};,68,https://leetcode.com/problems/cherry-pickup-ii,https://leetcode.com/problems/cherry-pickup-ii/solutions/3518692/c-both-memoization-tabulation-t-c-o-m-n-n-9-s-c-o-n-n/

class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        vector<int> dir={-1,0,1};
        int row = grid.size();
        int col = grid[0].size();
        int dp[row][col][col]; 

        for(int i = 0; i < row; i++){
            for(int j = 0; j < col; j++){
                for(int k = 0; k < col; k++){
                    dp[i][j][k] = -1;
                }
            }
        }
        int col1 = 0;
        int col2 = col - 1; 

        dp[0][col1][col2] = grid[0][col1] + grid[0][col2];

        int ans = dp[0][col1][col2]; 

        for(int i = 1; i < row; i++){ 
            for(int c1 = 0; c1 < col; c1++){ 
                for(int c2 = 0; c2 < col; c2++){
                    int prev = dp[i - 1][c1][c2];
                    if(prev >= 0){
                        for(int d1: dir){ 
                            col1 = d1 + c1; 
                            for(int d2: dir){ 
                                col2 = d2 + c2; 
                                if(inRange(col1, col) && inRange(col2, col)){
                                    dp[i][col1][col2] = max(dp[i][col1][col2], prev+(col1 == col2 ? grid[i][col1] : (grid[i][col1] + grid[i][col2])));

                                    ans = max(ans, dp[i][col1][col2]); 
                                }
                            }
                        }
                    }

                }
            }
        }
        return ans; 
    }
    bool inRange(int val, int limit){
        return 0 <= val && val < limit;
    }
};,3,https://leetcode.com/problems/cherry-pickup-ii,https://leetcode.com/problems/cherry-pickup-ii/solutions/1674112/well-detailed-explaination-java-c-easy-for-mind-to-accept-it/

class Solution {
public:
    const long long int mod = 1000000007;
    int maxArea(int hh, int ww, vector<int>& h, vector<int>& v) {
        // Sort
        sort(h.begin(), h.end());
        sort(v.begin(), v.end());


        // Horizontal
        vector<int> heights = {h[0]};
        int nh = h.size();
        for (int i=1; i<nh; i++) {
            heights.push_back(h[i]-h[i-1]);
        }
        heights.push_back(hh-h[nh-1]);

        // Vertical
        vector<int> lengths = {v[0]};
        int nv = v.size();
        for (int i=1; i<nv; i++) {
            lengths.push_back(v[i]-v[i-1]);
        }
        lengths.push_back(ww-v[nv-1]);

        // Take max
        long long int a = *max_element(heights.begin(), heights.end());
        long long int b = *max_element(lengths.begin(), lengths.end());

        // Multiply and return
        return (int)(a%mod*b%mod);
    }
