public:
    int kthFactor(int n, int k) {

        int res = n;
        int cnt = 0;
        int kk = k;
        for(int i=1;i<=n;i++)
        {
            if(k == 0)
                return res;

            if(n%i==0)
            {
                k--;
                cnt++;
                res = i;
            }
        }

        return cnt<kk?-1:res;
    }
