class Solution {
public:
  int minDays(int n)
{
    unordered_map<int, int> mp;
    queue<int> q;
    q.push(n);
    int count = 0;

    while (!q.empty())
    {
        int sz = q.size();

        while (sz--)
        {
            int org = q.front();
            q.pop();
            if (org == 0)
            {
                return count;
            }

            if (org % 3 == 0 and mp.find(org / 3) == mp.end())
            {
                q.push(org / 3);
                mp[org / 3]++;
            }

            if (org % 2 == 0 and mp.find(org / 2) == mp.end())
            {
                q.push(org / 2);
                mp[org / 2]++;
            }

            if (mp.find(org - 1) == mp.end())
            {
                q.push(org - 1);
                mp[org - 1]++;
            }
        }
        count++;
    }
    return 0;
}
