class Solution {
public:
    int maximumUniqueSubarray(vector<int>& nums) {
        unordered_map<int, int> seen;
        int l = 0, sum = 0, ans = 0;
        for (int r = 0; r < nums.size(); r++) {
            int x = nums[r];
            if (seen.find(x) != seen.end()) {
                int index = seen[x];
                while (l <= index) {  // Move the left side until index + 1
                    seen.erase(nums[l]);
                    sum -= nums[l];
                    l += 1;
                }
            }
            seen[x] = r;
            sum += x;
            ans = max(ans, sum);
        }
        return ans;
    }
