class Solution {
    static bool cmp(vector<int> &a, vector<int> &b) {
        return a[2] < b[2];
    }
    int find_prnt(int node, vector<int> &prnt) {
        if(node == prnt[node]) return node;
        return prnt[node] = find_prnt(prnt[node], prnt);
    }
    void unionn(int u, int v, vector<int> &prnt, vector<int> &rank) {
        int ulp_u = find_prnt(u, prnt), ulp_v = find_prnt(v, prnt);

        if(rank[ulp_u] > rank[ulp_v]) prnt[ulp_v] = ulp_u; 
        else if(rank[ulp_u] < rank[ulp_v]) prnt[ulp_u] = ulp_v;
        else {
            prnt[ulp_v] = ulp_u;
            rank[ulp_u]++;
        }
    }
public:
    vector<bool> distanceLimitedPathsExist(int n, vector<vector<int>>& edgeList, vector<vector<int>>& queries) {
        int m = queries.size(), p = 0;
        for(int i=0; i<m; i++) queries[i].push_back(i);

        sort(edgeList.begin(), edgeList.end(), cmp);
        sort(queries.begin(), queries.end(), cmp);

        vector<bool> ans(m);
        vector<int> prnt(n), rank(n);
        for(int i=0; i<n; i++) prnt[i] = i;

        for(auto q : queries) {
            while(p < edgeList.size() && edgeList[p][2] < q[2]) {
                unionn(edgeList[p][0], edgeList[p][1], prnt, rank), p++;
            }
            ans[q[3]] = find_prnt(q[0], prnt) == find_prnt(q[1], prnt);
        }
        return ans;
    }
};,78,https://leetcode.com/problems/checking-existence-of-edge-length-limited-paths,https://leetcode.com/problems/checking-existence-of-edge-length-limited-paths/solutions/3466250/sorting-union-find-c/

class Solution {

    // taken some help


    // First i get the index of  first "0", if it is not present then we will return the string itself
    // otherwise we will count the number of "0" after that index;
    // now we will shift that "0" by count number of times and fill all the place with "1"
    // this is because we can always make the string that contains only one "0";

    public String maximumBinaryString(String s){

        int n = s.length();

        int a = s.indexOf("0");
        if(a==-1) return s;

        int zero = 0;

        for(int i=a+1; i<n; i++){
            if(s.charAt(i)=='0') zero++;
        } 

        StringBuilder ans = new StringBuilder();
        ans.append("1".repeat(n));

        int x = a+zero;

        ans.replace(x,x+1,"0");
        return ans.toString();
    }
